void sobel(const uint8_t *input, uint8_t *output, int width, int height)
{
    /*Knob Variables Declaration Start*/
    float loop_perforation_factor = 1.0; // Range: [0.5, 1.0], Step: Real
    int precision_scale = 0;             // Range: [0, 1], Step: Integer
    int early_exit_enabled = 0;          // Range: [0, 1], Step: Integer
    int max_pixels = width * height;     // Range: [width * height * 0.5, width * height], Step: Integer
    /*Knob Variables Declaration End*/

    int total_pixels = (int)(height * loop_perforation_factor) * (int)(width * loop_perforation_factor);
    int processed_pixels = 0;

    for (int y = 0; y < height * loop_perforation_factor; y++) {
        for (int x = 0; x < width * loop_perforation_factor; x++) {

            if (x == 0 || x == width - 1 || y == 0 || y == height - 1) {
                output[y * width + x] = 0;
                continue;
            }

            // Load pixel values
            int p00 = input[(y - 1) * width + (x - 1)];
            int p01 = input[(y - 1) * width + x];
            int p02 = input[(y - 1) * width + (x + 1)];
            int p10 = input[y * width + (x - 1)];
            int p12 = input[y * width + (x + 1)];
            int p20 = input[(y + 1) * width + (x - 1)];
            int p21 = input[(y + 1) * width + x];
            int p22 = input[(y + 1) * width + (x + 1)];

            // Apply precision scaling if enabled
            if (precision_scale) {
                p00 = p00 >> 1;
                p01 = p01 >> 1;
                p02 = p02 >> 1;
                p10 = p10 >> 1;
                p12 = p12 >> 1;
                p20 = p20 >> 1;
                p21 = p21 >> 1;
                p22 = p22 >> 1;
            }

            // Compute gradients
            int gx = -p00 + p02 - 2 * p10 + 2 * p12 - p20 + p22;
            int gy = p00 + 2 * p01 + p02 - p20 - 2 * p21 - p22;

            // Compute gradient magnitude
            int mag = abs(gx) + abs(gy);
            if (mag > 255) mag = 255;

            output[y * width + x] = (uint8_t)mag;

            // Early exit if enabled and max_pixels reached
            processed_pixels++;
            if (early_exit_enabled && processed_pixels >= max_pixels) {
                return;
            }
        }
    }
}
